      "Santa Clara es, ante todo, ciudad universitaria: la Universidad Central Marta Abreu llena las calles de estudiantes de toda la isla y le da un pulso más joven, más irreverente, que a cualquier otra capital provincial cubana. El Mausoleo del Che Guevara, en la Plaza de la Revolución, recibe cada año a miles de visitantes, y muy cerca el monumento al Tren Blindado marca el sitio donde un grupo de guerrilleros descarriló el convoy militar que selló el triunfo de la Revolución en diciembre de 1958. Pero la ciudad no vive solo de historia: en El Mejunje, un patio cultural sin techo ni prejuicios, cabe desde una peña de trova hasta una noche de rock o una fiesta drag, algo poco común en el resto del país. Alrededor del Parque Vidal se junta gente de todas las edades a media tarde, y en esta sala pasa lo mismo: estudiantes, roqueros, trovadores y curiosos que llegan atraídos por esa fama de ciudad abierta.",
